const $=s=>document.querySelector(s);const gcd=(a,b)=>b?gcd(b,a%b):Math.abs(a);function frac(n,d=1){if(d<0){n=-n;d=-d}const g=gcd(n,d);return n===0?'0':d/g===1?String(n/g).replace('-','−'):`${String(n/g).replace('-','−')}/${d/g}`}const fmt=n=>String(n).replace('-','−').replace('.',',');const storage={get(k){try{return localStorage.getItem('fondasi-variable-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-variable-'+k,v);return true}catch{return false}}};const expressions={linear:{name:'3x + 2',value:x=>frac(6*x+4,2),sub:x=>`3 × (${fmt(x)}) + 2`,why:'Kalikan nilai x dengan 3, lalu tambahkan 2.'},square:{name:'x² + 2x',value:x=>frac(4*x*x+8*x,4),sub:x=>`(${fmt(x)})² + 2 × (${fmt(x)})`,why:'Nilai x yang sama dipakai pada kedua kemunculannya. Hitung pangkat dan perkalian sebelum penjumlahan.'},bracket:{name:'2(x + 1)',value:x=>frac(4*x+4,2),sub:x=>`2 × ((${fmt(x)}) + 1)`,why:'Hitung nilai kelompok x + 1 terlebih dahulu, lalu kalikan dengan 2.'},reciprocal:{name:'1/(x − 1)',value:x=>x===1?null:frac(2,2*x-2),sub:x=>`1/((${fmt(x)}) − 1)`,why:'Hitung penyebut x − 1. Hanya nilai x selain 1 yang boleh dipakai.'}};function update(){const x=Number($('#x').value),e=expressions[$('#expression').value],result=e.value(x);$('#x-out').value=fmt(x);$('#substitution').textContent=result===null?`${e.name} → ${e.sub(x)} = 1/0`:`${e.name} → ${e.sub(x)} = ${result}`;$('#feedback').textContent=result===null?'Pada x = 1, penyebutnya 0. Ekspresi tidak terdefinisi; 1/0 bukan bilangan hasil perhitungan.':`Untuk x = ${fmt(x)}, nilai ${e.name} adalah ${result}. ${e.why}`;$('#expression-heading').textContent=e.name;$('#values').replaceChildren();for(const v of [-2,0,1,2,4]){const tr=document.createElement('tr');for(const text of [fmt(v),e.value(v)??'Tidak terdefinisi']){const td=document.createElement('td');td.textContent=text;tr.append(td)}$('#values').append(tr)}$('#table-caption').textContent=`Perbandingan nilai ${e.name} untuk beberapa nilai x.`}$('#x').addEventListener('input',update);$('#expression').addEventListener('change',update);$('#reset').addEventListener('click',()=>{$('#x').value=4;$('#expression').value='linear';update()});update();function equation(){const x=Number($('#candidate').value),left=3*x+2;$('#equation').textContent=`3 × ${x} + 2 = ${left}. ${left===14?'14 = 14':'Tetapi '+left+' ≠ 14'}`;$('#equation-feedback').textContent=left===14?'x = 4 membuat ruas kiri bernilai 14, sama dengan ruas kanan. Jadi 4 adalah solusi.':`x = ${x} membuat ruas kiri bernilai ${left}, berbeda dari 14. Jadi ${x} bukan solusi persamaan ini.`}$('#candidate').addEventListener('change',equation);equation();$('#check').addEventListener('click',()=>{const v=document.querySelector('[name=awal]:checked')?.value;$('#check-feedback').textContent=!v?'Pilih satu dugaan terlebih dahulu.':v==='14'?'Tepat. Ganti x dengan 4, lalu hitung 3 × 4 + 2 = 14.':v==='36'?'3x adalah perkalian 3 × x. Mengganti x dengan 4 menghasilkan 3 × 4, bukan bilangan 34.':'Suku 2 tidak memuat x. Hanya 3 yang menjadi pengali x, sehingga 3 × 4 + 2 = 14.'});
const qs=[{t:'Nilai 2x + 5 untuk x = 3 adalah…',n:11,d:1,h:'Ganti x dengan 3. Kerjakan perkalian dahulu.',why:'2 × 3 + 5 = 6 + 5 = 11.'},{t:'Nilai x² + 2x untuk x = −2 adalah…',n:0,d:1,h:'Gunakan tanda kurung: (−2)² + 2 × (−2).',why:'4 + (−4) = 0. Kedua x diganti dengan −2.'},{t:'Koefisien x pada −x + 7 adalah…',n:-1,d:1,h:'−x berarti (−1) × x.',why:'Koefisien x adalah −1.'},{t:'Konstanta pada 5x − 3 adalah…',n:-3,d:1,h:'Tanda minus ikut pada suku konstanta.',why:'Konstantanya −3 karena 5x − 3 = 5x + (−3). '},{t:'Pada 3x + 2x = □x, berapa isi kotak?',n:5,d:1,h:'Tiga kali x ditambah dua kali x.',why:'3x + 2x = 5x. Koefisien hasilnya 5.'},{t:'Nilai 1/(x − 1) untuk x = 3 adalah…',n:1,d:2,h:'Hitung penyebut 3 − 1 terlebih dahulu.',why:'1/(3 − 1) = 1/2.'},{t:'Apakah x = 5 solusi 3x + 2 = 14? Hitung nilai ruas kirinya untuk memeriksa.',n:17,d:1,h:'Masukkan x = 5 ke 3x + 2. Tulis nilai ruas kiri, bukan nilai x.',why:'3 × 5 + 2 = 17. Karena 17 ≠ 14, x = 5 bukan solusi.'}];const solved=new Set();function progress(){$('#progress').textContent=`${solved.size} dari 8 latihan telah dijawab dengan tepat.`}function parse(s){const m=s.trim().replace(/−/g,'-').match(/^([+-]?\d+)(?:\s*\/\s*([+-]?\d+))?$/);if(!m)return null;const n=Number(m[1]),d=m[2]?Number(m[2]):1;return Number.isSafeInteger(n)&&Number.isSafeInteger(d)&&d!==0&&Math.abs(n)<=1000000&&Math.abs(d)<=1000000?{n,d}:null}$('#questions').innerHTML=qs.map((q,i)=>`<div class="question"><h3>Latihan ${i+1}</h3><p>${q.t}</p><form class="number-form" data-q="${i}"><label for="answer${i}">Jawaban latihan ${i+1}, pecahan atau bilangan bulat</label><div class="answer-line"><input id="answer${i}" type="text" inputmode="text" placeholder="misalnya -3" required autocomplete="off" aria-describedby="feedback${i}"><button class="button">Periksa jawaban</button></div></form><p id="feedback${i}" class="feedback" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.h}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('[data-q]').forEach(form=>form.addEventListener('submit',ev=>{ev.preventDefault();const i=Number(form.dataset.q),v=parse($('#answer'+i).value),q=qs[i],ok=v&&v.n*q.d===q.n*v.d;$('#feedback'+i).className='feedback '+(ok?'correct':'incorrect');$('#feedback'+i).textContent=!v?'Tulis bilangan bulat atau pecahan seperti -3 atau 1/2. Penyebut tidak boleh nol.':ok?'Tepat. '+q.why:'Belum tepat. Periksa arti variabel, tanda setiap suku, dan urutan operasinya. Gunakan petunjuk jika perlu.';if(ok)solved.add(i);progress()}));$('#check-domain').addEventListener('click',()=>{const v=document.querySelector('[name=domain]:checked')?.value,ok=v==='undefined';$('#domain-feedback').className='feedback '+(ok?'correct':'incorrect');$('#domain-feedback').textContent=!v?'Pilih satu jawaban terlebih dahulu.':ok?'Tepat. x − 1 = 0 pada x = 1, sehingga 1/(x − 1) tidak terdefinisi.':'Pada x = 1, penyebut x − 1 menjadi nol. Pembagian dengan nol tidak terdefinisi.';if(ok)solved.add(7);progress()});$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#reflection-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan pada peramban ini.':'Catatan belum bisa disimpan. Salin jika ingin menyimpannya.'});function complete(){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#progress').textContent='Bacaan ditandai selesai ✓'}if(storage.get('complete')==='yes')complete();$('#complete').addEventListener('click',()=>{const ok=storage.set('complete','yes');complete();$('#complete-note').textContent=ok?'Kemajuan tersimpan. Kamu dapat kembali berlatih kapan saja.':'Selesai. Kemajuan belum bisa disimpan pada peramban ini.'});
